const { ethers } = require('hardhat')

// ── Config ──────────────────────────────────────────────────────────────────
// Recreates soETH's two Ethereum Safes on this chain at the same addresses by replaying their
// original createProxyWithNonce calls. Anyone can send these. Each Safe comes up with its ORIGINAL
// 2024 signers, not today's, so fix its signers in Safe{Wallet} straight after.
const safes = [
  {
    name: 'Owner Safe (soETH multisig)',
    address: '0x6B26fAF3AD822695127B29ad242ac4B33D336F42',
    factory: '0x4e1DCf7AD4e460CfD30791CCC4F9c8a4f820ec67', // SafeProxyFactory 1.4.1
    // Ethereum tx 0xa29a4972e082c15276fb3851ccc7a45e35b32563805ee0e5f1853c34ee7981a0
    calldata: '',
  },
  {
    name: 'Solver Safe',
    address: '0xA7Fdc92eDa10eac8d6AfD3037d398929B57303D7',
    factory: '0xa6B71E26C5e0845f74c812102Ca7114b6a896AB2', // GnosisSafeProxyFactory 1.3.0
    // Ethereum tx 0x6a0d71a655456e0cc49f2bcd27fa8c3f10512eba2d3f0eba187d907036dafea5
    calldata: '',
  },
]

const safeAbi = [
  'function getOwners() view returns (address[])',
  'function getThreshold() view returns (uint256)',
]

// ── Execute ─────────────────────────────────────────────────────────────────
async function main() {
  const [signer] = await ethers.getSigners()
  console.log('Signer:', signer.address)

  for (const { name, address, factory, calldata } of safes) {
    console.log('---')
    if ((await ethers.provider.getCode(address)) === '0x') {
      console.log(`Creating ${name} at ${address}...`)
      const tx = await signer.sendTransaction({ to: factory, data: calldata })
      await tx.wait()
      console.log('  tx:', tx.hash)
      // Load-balanced RPCs can answer from a node that has not seen the new block yet, so retry.
      let code = '0x'
      for (let i = 0; i < 15 && code === '0x'; i++) {
        if (i > 0) await new Promise((resolve) => setTimeout(resolve, 2000))
        code = await ethers.provider.getCode(address)
      }
      if (code === '0x') {
        throw new Error(`${name} was not created at ${address}`)
      }
    } else {
      console.log(`${name} already exists at ${address}`)
    }
    const safe = new ethers.Contract(address, safeAbi, signer)
    console.log(`  signers: ${await safe.getThreshold()}-of-[${(await safe.getOwners()).join(', ')}]`)
  }
}

main()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error(error)
    process.exit(1)
  })
